/* Container for the ellipsis icon – ensures accessible click target */
.OG-icon.og-icon-ellipsis {
    position: relative;
    display: inline-block;
    min-width: 44px;
    min-height: 44px;
    cursor: pointer;
    color: var(--icon-ellipsis-color, var(--text-primary, #333));
    transition: color 0.2s ease;
}

/* Hover state: changes dot color to primary brand color */
.OG-icon.og-icon-ellipsis:hover {
    color: var(--primary-color, #0066cc);
}
